using PdfSharp;
using PdfSharp.Drawing;
using PdfSharp.Pdf;

namespace DocProc.Pipeline.Tests.Pdf;

/// <summary>
/// The two PDFs of the demo data (docs/09 "Demo data"), drawn once with PDFsharp and committed under
/// <c>fixtures/demo/tenant-a</c>: a two-page invoice and a one-page delivery note from Bio-Hof Müller to tenant A, both
/// with a text layer. They are not regenerated by the normal test run (PDFsharp writes a new document id and timestamp
/// every time, which would change the bytes and with them every LLM request hash); <c>DemoFixtureTests</c> writes them
/// only when <c>REGENERATE_DEMO_PDFS=1</c>, after which the replay fixtures must be regenerated as well.
/// </summary>
internal static class DemoPdfs
{
    public const string InvoiceFileName = "BioHof-Mueller_Rechnung_2026-131.pdf";
    public const string DeliveryNoteFileName = "BioHof-Mueller_Lieferung_L-2026-0457.pdf";

    private const double Left = 50;
    private const double Right = 545;

    private static readonly (string Pos, string Article, string Quantity, string Unit, string Price, string Total)[] InvoiceLinesPage1 =
    [
        ("1", "Eier Freiland Größe M, 30 Stück", "8", "Pck", "9,60", "76,80"),
        ("2", "Bergkäse 12 Monate gereift", "2,4", "kg", "24,50", "58,80"),
        ("3", "Bauernbutter 250 g", "24", "Stk", "2,95", "70,80"),
        ("4", "Speisekartoffeln festkochend", "50", "kg", "1,40", "70,00"),
        ("5", "Karotten", "10", "kg", "1,90", "19,00"),
        ("6", "Rote Bete gekocht, vakuumiert", "5", "kg", "3,20", "16,00"),
        ("7", "Apfelsaft naturtrüb 1 l", "12", "Fl", "2,80", "33,60"),
        ("8", "Bio-Joghurt natur 500 g", "20", "Becher", "1,65", "33,00"),
    ];

    private static readonly (string Pos, string Article, string Quantity, string Unit, string Price, string Total)[] InvoiceLinesPage2 =
    [
        ("9", "Blütenhonig 500 g", "6", "Glas", "6,90", "41,40"),
        ("10", "Lieferpauschale Rosenheim", "1", "pauschal", "12,00", "12,00"),
    ];

    private static readonly (string Pos, string Article, string Quantity, string Unit, string Remark)[] DeliveryLines =
    [
        ("1", "Eier Freiland Größe M, 30 Stück", "6", "Pck", string.Empty),
        ("2", "Bauernbutter 250 g", "20", "Stk", string.Empty),
        ("3", "Speisekartoffeln festkochend", "25", "kg", string.Empty),
        ("4", "Bio-Joghurt natur 500 g", "12", "Becher", string.Empty),
        ("5", "Rucola", "2", "kg", "statt 3 kg, Rest folgt"),
        ("6", "Apfelsaft naturtrüb 1 l", "12", "Fl", "inkl. Pfandkiste"),
    ];

    /// <summary>Invoice 2026-131 over two pages: 10 lines, 431,40 EUR net, 7 % VAT 30,20 EUR, 461,60 EUR gross; payment terms in words only.</summary>
    public static byte[] Invoice() => Build("Rechnung 2026-131", new DateTime(2026, 10, 28, 16, 12, 0, DateTimeKind.Utc), document =>
    {
        using (var gfx = NewPage(document))
        {
            Letterhead(gfx);
            AddressBlock(gfx);
            InfoRow(gfx, 136, "Rechnungsnummer", "2026-131");
            InfoRow(gfx, 150, "Rechnungsdatum", "28.10.2026");
            InfoRow(gfx, 164, "Lieferdatum", "28.10.2026");
            InfoRow(gfx, 178, "Kundennummer", "0815");
            Text(gfx, Left, 232, 20, "Rechnung", bold: true);
            Text(gfx, Left, 254, 10, "Wir berechnen Ihnen für die Lieferung vom 28.10.2026:");

            var y = InvoiceTableHeader(gfx, 282);
            foreach (var line in InvoiceLinesPage1)
            {
                y = InvoiceRow(gfx, y, line);
            }

            Rule(gfx, y - 8);
            Text(gfx, 330, y + 8, 10, "Zwischensumme Seite 1");
            RightText(gfx, Right, y + 8, 10, "378,00 EUR");
            Footer(gfx, "Seite 1 von 2");
        }

        using (var gfx = NewPage(document))
        {
            Text(gfx, Left, 60, 10, "Bio-Hof Müller · Rechnung 2026-131 vom 28.10.2026");
            Rule(gfx, 68);
            var y = InvoiceTableHeader(gfx, 96);
            Text(gfx, 330, y, 10, "Übertrag");
            RightText(gfx, Right, y, 10, "378,00 EUR");
            y += 18;
            foreach (var line in InvoiceLinesPage2)
            {
                y = InvoiceRow(gfx, y, line);
            }

            Rule(gfx, y - 8);
            Text(gfx, 330, y + 10, 10, "Nettobetrag");
            RightText(gfx, Right, y + 10, 10, "431,40 EUR");
            Text(gfx, 330, y + 26, 10, "zzgl. 7 % MwSt.");
            RightText(gfx, Right, y + 26, 10, "30,20 EUR");
            Rule(gfx, y + 34, 330);
            Text(gfx, 330, y + 50, 12, "Rechnungsbetrag", bold: true);
            RightText(gfx, Right, y + 50, 12, "461,60 EUR", bold: true);

            Text(gfx, Left, y + 96, 10, "Zahlbar innerhalb von 14 Tagen ohne Abzug.");
            Text(gfx, Left, y + 112, 10, "Bitte geben Sie bei der Überweisung die Rechnungsnummer 2026-131 an.");
            Text(gfx, Left, y + 144, 10, "Vielen Dank für Ihren Einkauf! Ihr Bio-Hof Müller, aus der Region für die Region.");
            Text(gfx, Left, y + 160, 9, "Alle Erzeugnisse aus kontrolliert biologischem Anbau, Öko-Kontrollstelle DE-ÖKO-006.");
            Footer(gfx, "Seite 2 von 2");
        }
    });

    /// <summary>
    /// Delivery L-2026-0457: a farm's delivery slip without prices whose title is just "Lieferung" and which says that
    /// the invoice follows, so the keyword rules find no type and stage 4 asks the LLM classifier.
    /// </summary>
    public static byte[] DeliveryNote() => Build("Lieferung L-2026-0457", new DateTime(2026, 10, 30, 6, 40, 0, DateTimeKind.Utc), document =>
    {
        using var gfx = NewPage(document);
        Letterhead(gfx);
        AddressBlock(gfx);
        InfoRow(gfx, 136, "Lieferung Nr.", "L-2026-0457");
        InfoRow(gfx, 150, "Liefertag", "30.10.2026");
        InfoRow(gfx, 164, "Tour", "Rosenheim Nord");
        InfoRow(gfx, 178, "Kundennummer", "0815");
        Text(gfx, Left, 232, 20, "Lieferung", bold: true);
        Text(gfx, Left, 254, 10, "Folgende Waren haben wir Ihnen heute geliefert:");

        var y = 282d;
        var header = new XFont(TestPdfs.FontFamily, 9.5, XFontStyleEx.Bold);
        gfx.DrawString("Pos", header, XBrushes.Black, Left, y);
        gfx.DrawString("Artikel", header, XBrushes.Black, 80, y);
        gfx.DrawString("Menge", header, XBrushes.Black, 300, y);
        gfx.DrawString("Einheit", header, XBrushes.Black, 345, y);
        gfx.DrawString("Bemerkung", header, XBrushes.Black, 405, y);
        Rule(gfx, y + 6);
        y += 22;
        foreach (var (pos, article, quantity, unit, remark) in DeliveryLines)
        {
            Text(gfx, Left, y, 10, pos);
            Text(gfx, 80, y, 10, article);
            RightText(gfx, 330, y, 10, quantity);
            Text(gfx, 345, y, 10, unit);
            Text(gfx, 405, y, 10, remark);
            y += 18;
        }

        Rule(gfx, y - 8);
        Text(gfx, Left, y + 24, 10, "Die Rechnung folgt separat zum Monatsende.");
        Text(gfx, Left, y + 40, 10, "Leergut und Pfandkisten nehmen wir bei der nächsten Lieferung gerne wieder mit.");
        Text(gfx, Left, y + 88, 10, "Ware vollständig und in einwandfreiem Zustand erhalten:");
        gfx.DrawLine(new XPen(XColors.Black, 0.6), Left, y + 140, 260, y + 140);
        Text(gfx, Left, y + 152, 8, "Datum, Unterschrift Empfänger");
        gfx.DrawLine(new XPen(XColors.Black, 0.6), 330, y + 140, Right, y + 140);
        Text(gfx, 330, y + 152, 8, "Fahrer");
        Footer(gfx, "Seite 1 von 1");
    });

    private static byte[] Build(string title, DateTime createdAt, Action<PdfDocument> compose)
    {
        TestPdfs.EnsureFonts();
        using var document = new PdfDocument();
        document.Info.Title = title;
        document.Info.Author = "Bio-Hof Müller";
        document.Info.Creator = "Hofladen-Kasse 3.2";
        document.Info.CreationDate = createdAt;
        compose(document);
        using var stream = new MemoryStream();
        document.Save(stream, closeStream: false);
        return stream.ToArray();
    }

    private static XGraphics NewPage(PdfDocument document)
    {
        var page = document.AddPage();
        page.Size = PageSize.A4;
        return XGraphics.FromPdfPage(page);
    }

    private static void Letterhead(XGraphics gfx)
    {
        Text(gfx, Left, 60, 16, "Bio-Hof Müller", bold: true);
        Text(gfx, Left, 76, 9, "Inh. Josef Müller · Dorfstraße 4 · 83135 Schechen · Tel. 08039 904127 · hof@biohof-mueller.example");
        Rule(gfx, 84);
    }

    private static void AddressBlock(XGraphics gfx)
    {
        Text(gfx, Left, 118, 7, "Bio-Hof Müller · Dorfstraße 4 · 83135 Schechen");
        Text(gfx, Left, 136, 11, "Gasthaus zur Post GmbH");
        Text(gfx, Left, 150, 11, "Küche / Wareneingang");
        Text(gfx, Left, 164, 11, "Hauptstraße 12");
        Text(gfx, Left, 178, 11, "83022 Rosenheim");
    }

    private static void InfoRow(XGraphics gfx, double baseline, string label, string value)
    {
        Text(gfx, 345, baseline, 10, label);
        RightText(gfx, Right, baseline, 10, value);
    }

    private static double InvoiceTableHeader(XGraphics gfx, double y)
    {
        var header = new XFont(TestPdfs.FontFamily, 9.5, XFontStyleEx.Bold);
        gfx.DrawString("Pos", header, XBrushes.Black, Left, y);
        gfx.DrawString("Artikel", header, XBrushes.Black, 80, y);
        RightAligned(gfx, "Menge", header, 330, y);
        gfx.DrawString("Einheit", header, XBrushes.Black, 340, y);
        RightAligned(gfx, "Einzelpreis", header, 465, y);
        RightAligned(gfx, "Gesamt", header, Right, y);
        Rule(gfx, y + 6);
        return y + 22;
    }

    private static double InvoiceRow(XGraphics gfx, double y, (string Pos, string Article, string Quantity, string Unit, string Price, string Total) line)
    {
        Text(gfx, Left, y, 10, line.Pos);
        Text(gfx, 80, y, 10, line.Article);
        RightText(gfx, 330, y, 10, line.Quantity);
        Text(gfx, 340, y, 10, line.Unit);
        RightText(gfx, 465, y, 10, line.Price);
        RightText(gfx, Right, y, 10, line.Total);
        return y + 18;
    }

    private static void Footer(XGraphics gfx, string pageLabel)
    {
        Rule(gfx, 778);
        Text(gfx, Left, 790, 7.5, "Bio-Hof Müller · Inh. Josef Müller · Steuernummer 156/220/40817 · USt-IdNr. DE287654321");
        Text(gfx, Left, 801, 7.5, "VR-Bank Rosenheim-Chiemsee · IBAN DE20 7016 9165 0000 1234 56 · BIC GENODEF1VRR");
        RightText(gfx, Right, 820, 8, pageLabel);
    }

    private static void Rule(XGraphics gfx, double y, double from = Left) =>
        gfx.DrawLine(new XPen(XColors.Gray, 0.5), from, y, Right, y);

    private static void Text(XGraphics gfx, double x, double baseline, double size, string text, bool bold = false)
    {
        if (text.Length == 0)
        {
            return;
        }

        gfx.DrawString(text, new XFont(TestPdfs.FontFamily, size, bold ? XFontStyleEx.Bold : XFontStyleEx.Regular), XBrushes.Black, x, baseline);
    }

    private static void RightText(XGraphics gfx, double right, double baseline, double size, string text, bool bold = false) =>
        RightAligned(gfx, text, new XFont(TestPdfs.FontFamily, size, bold ? XFontStyleEx.Bold : XFontStyleEx.Regular), right, baseline);

    private static void RightAligned(XGraphics gfx, string text, XFont font, double right, double baseline)
    {
        var width = gfx.MeasureString(text, font).Width;
        gfx.DrawString(text, font, XBrushes.Black, right - width, baseline);
    }
}
